 "content": "def transform(grid):
    out = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    solid_rows = [(r, row[0]) for r, row in enumerate(grid) if row and row[0] != 0 and all(x == row[0] for x in row)]
    if not solid_rows:
        return out
    # Extend the solid horizontal stripe in the color of the other stripe,
    # immediately below it, aligned with the bounds of that stripe.
    for r, color in solid_rows:
        other = next((rr for rr, row in enumerate(grid) if rr != r and any(v != 0 for v in row) and not all(v == color for v in row)), None)
        if other is None:
            continue
        cells = [c for c, value in enumerate(grid[other]) if value != 0]
        if cells:
            rr = r + 1 if r + 1 < rows else r - 1
            for c in cells:
                out[rr][c] = grid[other][c]
    return out
